mapper.select:
SELECT o.id, o.order_no, o.warehouse_id, w.name AS warehouse_name, o.supplier_id, o.supplier_name, o.expect_arrive_time, o.status, o.total_expect_qty, o.total_received_qty, o.remark, o.create_time, o.update_time FROM inbound_order o LEFT JOIN warehouse w ON w.id = o.warehouse_id AND w.deleted = 0 WHERE o.deleted = 0
AND (o.order_no LIKE CONCAT('%', #{query.keyword}, '%') OR o.supplier_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND o.warehouse_id = #{query.warehouseId}
AND o.status = #{query.status}
AND o.create_time >= #{query.beginTime}
AND o.create_time < DATE_ADD(#{query.endTime}, INTERVAL 1 DAY)
ORDER BY o.id DESC

mapper.update:
UPDATE inbound_order
SET status             = #{status},
    total_received_qty = #{totalReceivedQty},
    update_by          = #{updateBy}
WHERE id = #{id}
  AND deleted = 0

UPDATE inbound_order
SET status    = 'CANCELLED',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'CREATED'
  AND deleted = 0

UPDATE inbound_order
SET status    = 'PUTAWAY_DONE',
    update_by = #{updateBy}
WHERE id = #{id}
  AND status = 'RECEIVED'
  AND deleted = 0
